const fs=require('node:fs');
const paths=['/srv/projects/Sexshop','/srv/projects/Sexshop/current','/srv/projects/Sexshop/data/catalog.json'];
const out={scope:'READ_ONLY',paths:{}};
for(const p of paths){try{const s=fs.lstatSync(p);out.paths[p]={present:true,isSymlink:s.isSymbolicLink(),isDirectory:s.isDirectory(),owner:s.uid,bytes:s.size,target:s.isSymbolicLink()?fs.readlinkSync(p):null}}catch(e){out.paths[p]={present:false,error:e.code}}}
(async()=>{out.public=[];
for(const u of ['https://sevelora.eu/','https://sevelora.eu/catalogo','https://www.sevelora.eu/']){
 try{const r=await fetch(u,{redirect:'manual',signal:AbortSignal.timeout(10000)});const html=await r.text();
 const links=[...html.matchAll(/href="(https?:[^"]+)"/g)].slice(0,200).map(m=>m[1].replace(/&amp;/g,'&')).filter(h=>h.includes('awin1.com'));
 out.public.push({url:u,status:r.status,location:r.headers.get('location'),htmlBytes:html.length,affiliateLinkCount:links.length,affiliateSample:links[0]?.replace(/p=[^&]+/,'p=REDACTED')??null,hasPageTitle:/Sevelora/i.test(html)});
 }catch(e){out.public.push({url:u,error:e.message})}}
console.log(JSON.stringify(out));
})().catch(e=>{console.error(e);process.exitCode=1});
